function longestSteadySubsequence(nums: number[], k: number): number {
  const n = nums.length;
  let best = 2;
  for (let s = 0; s < k; s++) {
    const f = new Array(n).fill(1);
    for (let i = 0; i < n; i++)
      for (let j = 0; j < i; j++)
        if ((nums[j] + nums[i]) % k === s) f[i] = Math.max(f[i], f[j] + 1);
    for (const v of f) best = Math.max(best, v);
  }
  return best;
}

