        n = len(nums)
        best = 2
        for s in range(k):
            f = [1] * n
            for i in range(n):
                for j in range(i):
                    if (nums[j] + nums[i]) % k == s:
                        f[i] = max(f[i], f[j] + 1)
            best = max(best, max(f))
        return best

