function longestSteadySubsequence(nums: number[], k: number): number {
  const n = nums.length;
  const dp: Int32Array[] = Array.from({ length: n }, () => new Int32Array(k));
  let best = 2;
  for (let i = 0; i < n; i++)
    for (let j = 0; j < i; j++) {
      const s = (nums[j] + nums[i]) % k;
      const len = Math.max(dp[j][s], 1) + 1; // dp[j][s] is 0 when j starts the chain
      if (len > dp[i][s]) dp[i][s] = len;
      if (len > best) best = len;
    }
  return best;
}

